local DefaultScale = 39.37
local DefaultMcGrav = 1100.0 * (DefaultScale / 39.37)
local JumpPower = math.sqrt(2.0 * DefaultMcGrav * 1.252 * DefaultScale) -- ~329.36 at scale 39.37 (legacy 318 was moon-gravity without ply:SetGravity)
local CrouchedWalkSpeed = 1.30 / 4.317 -- ~0.301135 (MC sneak 1.30 m/s vs walk 4.317 m/s)
local StepSize = 0.60 * DefaultScale -- ~23.622 HU at scale 39.37 (steps slabs, stairs & beds)
local PlayerHalfWidth = 0.29
local PlayerHeight = 1.78

local MCGM = {
    Version = VERSION,
    Maps = (_G.MCGM_PHYSICS and _G.MCGM_PHYSICS.Maps) or {},
    ActiveMap = nil,
}
_G.MCGM_PHYSICS = MCGM

local function ApplyDlightChunkFix()
    if not CLIENT then return end
    if IsConCommandBlocked and IsConCommandBlocked("r_dynamic") then return end
    local r_dyn = GetConVar("r_dynamic")
    if not r_dyn then return end
    if MCGM.ActiveMap and cv_fix_dlight_chunks then
        if saved_r_dynamic == nil then
            saved_r_dynamic = r_dyn:GetString()
        end
        if r_dyn:GetString() ~= "0" then
            RunConsoleCommand("r_dynamic", "0")
        end
    elseif saved_r_dynamic ~= nil then
        RunConsoleCommand("r_dynamic", saved_r_dynamic)
        saved_r_dynamic = nil
    end
end

local function RestoreDlightSetting()
    if not CLIENT or saved_r_dynamic == nil then return end
    if IsConCommandBlocked and IsConCommandBlocked("r_dynamic") then return end
    RunConsoleCommand("r_dynamic", saved_r_dynamic)
    saved_r_dynamic = nil
end

if CLIENT then
    cvars.AddChangeCallback("mcgm_fix_dlight_chunks", function(_, _, n)
        cv_fix_dlight_chunks = (tonumber(n) or 0) ~= 0
        ApplyDlightChunkFix()
    end, "MCGM_Cache")
end

function _G.MCGM_RegisterMap(mapName, data)
    if not isstring(mapName) or not istable(data) then return end
    local key = string.lower(mapName)
    MCGM.Maps[key] = data
    if string.lower(game.GetMap() or "") == key then
        MCGM.ActiveMap = data
        ApplyDlightChunkFix()
    end
end

local function LoadCurrentMapData()
    local curMap = string.lower(game.GetMap() or "")
    if curMap == "" then
        MCGM.ActiveMap = nil
        return nil
    end
    local existing = MCGM.Maps[curMap]
    if existing then
        MCGM.ActiveMap = existing
        ApplyDlightChunkFix()
        return existing
    end
    for _, dir in ipairs(MAP_DIRS) do
        local mapFile = dir .. curMap .. ".lua"
        if file.Exists(mapFile, "LUA") then
            if SERVER then
                AddCSLuaFile(mapFile)
            end
            include(mapFile)
            if MCGM.Maps[curMap] then
                MCGM.ActiveMap = MCGM.Maps[curMap]
                ApplyDlightChunkFix()
                return MCGM.ActiveMap
            end
        end
    end
    MCGM.ActiveMap = nil
    return nil
end

LoadCurrentMapData()

local function GetActiveMapConfig()
    if MCGM.ActiveMap then return MCGM.ActiveMap end
    return LoadCurrentMapData()
end

if SERVER then
    -- Prevent "Node Graph out of Date. Rebuilding..." on MCGM maps (which omit info_node)
    if GetActiveMapConfig() then
        RunConsoleCommand("ai_norebuildgraph", "1")
    end
end

local function IsPhysicsEnabled(mapCfg)
    if not mapCfg then return false end
    local mode = cv_enabled
    if mode == 0 then return false end
    if mode >= 1 then return true end
    if mapCfg.enabled_by_default ~= nil then
        return mapCfg.enabled_by_default == true
    end
    return mapCfg.default_mc_physics ~= false
end

function MCGM.IsMapActive()
    local cfg = GetActiveMapConfig()
    local active = IsPhysicsEnabled(cfg)
    _G.MCGM_PHYSICS_ACTIVE = active
    return active
end

-- Coexist cleanly with mcgm_smooth_fall.lua (regardless of alphabetical load order):
-- suppress its FinishMove / CalcView hooks whenever MCGM physics is active OR explicitly disabled (0 = vanilla GMod).
local function ShouldSuppressSmoothFall()
    if cv_enabled == 0 then return true end
    return MCGM.IsMapActive()
end

local function SyncSmoothFallHooks()
    if MCGM.SmoothFallSynced then return end
    MCGM.IsMapActive()
    local tbl = hook.GetTable()
    if not tbl then return end

    local fm = tbl.FinishMove
    local wrappedAny = false
    if fm then
        local origFinish = fm["MCGM_SmoothBlockDescent"]
        if origFinish and origFinish ~= MCGM.SmoothFallWrappedFinish then
            MCGM.SmoothFallOrigFinish = origFinish
            MCGM.SmoothFallWrappedFinish = function(ply, mv)
                if ShouldSuppressSmoothFall() then
                    if IsValid(ply) then
                        ply.mcgm_sf_cam_z = 0
                    end
                    return
                end
                return MCGM.SmoothFallOrigFinish(ply, mv)
            end
            hook.Add("FinishMove", "MCGM_SmoothBlockDescent", MCGM.SmoothFallWrappedFinish)
            wrappedAny = true
        end
    end

    if CLIENT then
        local cv = tbl.CalcView
        if cv then
            local origCam = cv["MCGM_SmoothBlockCamera"]
            if origCam and origCam ~= MCGM.SmoothFallWrappedCam then
                MCGM.SmoothFallOrigCam = origCam
                MCGM.SmoothFallWrappedCam = function(ply, origin, angles, fov, znear, zfar)
                    if ShouldSuppressSmoothFall() then
                        if IsValid(ply) then
                            ply.mcgm_sf_cam_z = 0
                        end
                        return
                    end
                    return MCGM.SmoothFallOrigCam(ply, origin, angles, fov, znear, zfar)
                end
                hook.Add("CalcView", "MCGM_SmoothBlockCamera", MCGM.SmoothFallWrappedCam)
                wrappedAny = true
            end
        end
    end

    if wrappedAny or (fm and fm["MCGM_SmoothBlockDescent"] == MCGM.SmoothFallWrappedFinish) then
        MCGM.SmoothFallSynced = true
    end
end

local VANILLA_MINS = Vector(-16, -16, 0)
local VANILLA_MAXS = Vector(16, 16, 72)
local VANILLA_DUCK_MAXS = Vector(16, 16, 36)
local VANILLA_VIEW = Vector(0, 0, 64)
local VANILLA_DUCK_VIEW = Vector(0, 0, 28)

local function NearlySameVec(a, b)
    if not a or not b then return false end
    return math.abs(a.x - b.x) < 0.05 and math.abs(a.y - b.y) < 0.05 and math.abs(a.z - b.z) < 0.05
end

local function ApplyHullAndEyes(ply, mins, maxs, dmaxs, viewOff, duckViewOff)
    local cache = ply._mcgmHullCache
    if cache
        and math.abs(cache.minX - mins.x) < 0.05 and math.abs(cache.minY - mins.y) < 0.05 and math.abs(cache.minZ - mins.z) < 0.05
        and math.abs(cache.maxX - maxs.x) < 0.05 and math.abs(cache.maxY - maxs.y) < 0.05 and math.abs(cache.maxZ - maxs.z) < 0.05
        and math.abs(cache.dmaxX - dmaxs.x) < 0.05 and math.abs(cache.dmaxY - dmaxs.y) < 0.05 and math.abs(cache.dmaxZ - dmaxs.z) < 0.05
        and math.abs(cache.viewX - viewOff.x) < 0.05 and math.abs(cache.viewY - viewOff.y) < 0.05 and math.abs(cache.viewZ - viewOff.z) < 0.05
        and math.abs(cache.dviewX - duckViewOff.x) < 0.05 and math.abs(cache.dviewY - duckViewOff.y) < 0.05 and math.abs(cache.dviewZ - duckViewOff.z) < 0.05
    then
        return
    end
    local curMin, curMax = ply:GetHull()
    if not NearlySameVec(curMin, mins) or not NearlySameVec(curMax, maxs) then
        ply:SetHull(mins, maxs)
    end
    local curDMin, curDMax = ply:GetHullDuck()
    if not NearlySameVec(curDMin, mins) or not NearlySameVec(curDMax, dmaxs) then
        ply:SetHullDuck(mins, dmaxs)
    end
    if not NearlySameVec(ply:GetViewOffset(), viewOff) then
        ply:SetViewOffset(viewOff)
    end
    if not NearlySameVec(ply:GetViewOffsetDucked(), duckViewOff) then
        ply:SetViewOffsetDucked(duckViewOff)
    end
    if not cache then
        cache = {}
        ply._mcgmHullCache = cache
    end
    cache.minX, cache.minY, cache.minZ = mins.x, mins.y, mins.z
    cache.maxX, cache.maxY, cache.maxZ = maxs.x, maxs.y, maxs.z
    cache.dmaxX, cache.dmaxY, cache.dmaxZ = dmaxs.x, dmaxs.y, dmaxs.z
    cache.viewX, cache.viewY, cache.viewZ = viewOff.x, viewOff.y, viewOff.z
    cache.dviewX, cache.dviewY, cache.dviewZ = duckViewOff.x, duckViewOff.y, duckViewOff.z
end

local function SnapshotPlayerDefaults(ply)
    if not IsValid(ply) or ply._mcgmOrig then return end
    local hMin, hMax = ply:GetHull()
    local dMin, dMax = ply:GetHullDuck()
    ply._mcgmOrig = {
        mins = hMin or VANILLA_MINS,
        maxs = hMax or VANILLA_MAXS,
        dmaxs = dMax or VANILLA_DUCK_MAXS,
        view = ply:GetViewOffset() or VANILLA_VIEW,
        dview = ply:GetViewOffsetDucked() or VANILLA_DUCK_VIEW,
        walk = ply:GetWalkSpeed() > 0 and ply:GetWalkSpeed() or 200,
        run = ply:GetRunSpeed() > 0 and ply:GetRunSpeed() or 400,
        slow = ply:GetSlowWalkSpeed() > 0 and ply:GetSlowWalkSpeed() or 100,
        crouch = ply:GetCrouchedWalkSpeed() > 0 and ply:GetCrouchedWalkSpeed() or 0.3,
        jump = ply:GetJumpPower() > 0 and ply:GetJumpPower() or 200,
        step = ply:GetStepSize() > 0 and ply:GetStepSize() or 18,
        duck = ply:GetDuckSpeed() > 0 and ply:GetDuckSpeed() or 0.3,
        unduck = ply:GetUnDuckSpeed() > 0 and ply:GetUnDuckSpeed() or 0.3,
    }
end

local function RevertPlayerDefaults(ply)
    if not IsValid(ply) then return end
    ply._mcgmCamStepZ = 0
    ply._mcgmSpLastZ = nil
    ply._mcgmSpLastGround = nil
    ply._mcgmLastOriginZ = nil
    ply._mcgmLastViewOffZ = nil
    ply._mcgmLastGround = nil
    ply._mcgmHullCache = nil
    ply._mcgmBobPhase = 0
    ply._mcgmBobBlend = 0
    ply.mcgm_sf_cam_z = 0
    ply._mcgmRing = nil
    ply._mcgmTickCtx = nil
    if not ply._mcgmApplied then return end
    ply._mcgmApplied = false
    local orig = ply._mcgmOrig
    if orig then
        ApplyHullAndEyes(ply, orig.mins, orig.maxs, orig.dmaxs, orig.view, orig.dview)
        ply:SetWalkSpeed(orig.walk)
        ply:SetRunSpeed(orig.run)
        ply:SetSlowWalkSpeed(orig.slow)
        ply:SetCrouchedWalkSpeed(orig.crouch)
        ply:SetJumpPower(orig.jump)
        ply:SetStepSize(orig.step)
        ply:SetDuckSpeed(orig.duck)
        ply:SetUnDuckSpeed(orig.unduck)
    else
        ApplyHullAndEyes(ply, VANILLA_MINS, VANILLA_MAXS, VANILLA_DUCK_MAXS, VANILLA_VIEW, VANILLA_DUCK_VIEW)
        ply:SetWalkSpeed(200)
        ply:SetRunSpeed(400)
        ply:SetSlowWalkSpeed(100)
        ply:SetCrouchedWalkSpeed(0.3)
        ply:SetJumpPower(200)
        ply:SetStepSize(18)
        ply:SetDuckSpeed(0.3)
        ply:SetUnDuckSpeed(0.3)
    end
    ply._mcgmHullCache = nil
    ply:SetGravity(0)
end

local function OnPhysicsEnabledChanged()
    SyncSmoothFallHooks()
    local active = MCGM.IsMapActive()
    if not active then
        if SERVER then
            for _, ply in ipairs(player.GetAll()) do
                RevertPlayerDefaults(ply)
            end
        elseif CLIENT then
            local lp = LocalPlayer()
            if IsValid(lp) then
                RevertPlayerDefaults(lp)
            end
        end
    end
end

