if SERVER then
    local function CanTogglePhysics(ply)
        if not IsValid(ply) then return true end
        if game.SinglePlayer() then return true end
        return ply:IsAdmin() or ply:IsListenServerHost()
    end

    local function TogglePhysicsMode(ply)
        if not CanTogglePhysics(ply) then
            if IsValid(ply) then
                ply:ChatPrint("[MCGM] Only admin/host can toggle map physics.")
            end
            return
        end
        local curActive = MCGM.IsMapActive()
        local nextVal = curActive and "0" or "1"
        RunConsoleCommand("mcgm_physics_enabled", nextVal)
        local msg = curActive
            and "[MCGM] Minecraft physics: OFF (Vanilla GMod physics restored)"
            or "[MCGM] Minecraft physics: ON"
        PrintMessage(HUD_PRINTTALK, msg)
    end

    concommand.Add("mcgm_toggle_physics", function(ply)
        TogglePhysicsMode(ply)
    end, nil, "Toggle Minecraft physics ON/OFF live without restarting the map")

    hook.Add("PlayerSay", "MCGM_PhysicsChatToggle", function(ply, text)
        local cmd = string.lower(string.Trim(text or ""))
        if cmd == "!mcphysics" or cmd == "/mcphysics" or cmd == "!physics" or cmd == "/physics" then
            TogglePhysicsMode(ply)
            return ""
        end
    end)
end

-- Predicted 64-tick circular ring buffer keyed strictly by simulation tick
local function GetSimTick()
    local ti = engine.TickInterval()
    if ti <= 0 then ti = 1 / 66.666 end
    return math.floor(CurTime() / ti + 0.5)
end

local function GetTickState(ply, tick)
    local ring = ply._mcgmRing
    if not ring then return nil end
    local entry = ring[tick % 64]
    if entry and entry.tick == tick then
        return entry
    end
    return nil
end

local function StoreTickState(ply, tick, onGround, guardGrounded, fromJump, x, y, z, vx, vy, vz, peakZ, fwdHeld, spdHeld, wTapTime, sprintActive, sprinting)
    local ring = ply._mcgmRing
    if not ring then
        ring = {}
        for i = 0, 63 do
            ring[i] = {}
        end
        ply._mcgmRing = ring
    end
    local st = ring[tick % 64]
    st.tick = tick
    st.on_ground = onGround
    st.guard_grounded = guardGrounded
    st.from_jump = fromJump
    st.x = x
    st.y = y
    st.z = z
    st.vx = vx
    st.vy = vy
    st.vz = vz
    st.peak_z = peakZ
    st.fwd_held = fwdHeld
    st.spd_held = spdHeld
    st.w_tap_time = wTapTime
    st.sprint_active = sprintActive
    st.sprinting = sprinting
end

-- Supports both keyed-array buckets (`mapCfg.buckets[cx][cy][kind] = {x0,y0,z0,x1,y1,z1,...}`)
-- and legacy tuple-list buckets (`mapCfg.zones.buckets[cx][cy] = {{x0,y0,z0,x1,y1,z1,kind}, ...}`).
local function NormalizeKind(k, kindWanted)
    if k == kindWanted then return true end
    if kindWanted == "climb" and (k == "climb" or k == "ladder" or k == "vine") then
        return true
    end
    return false
end

local function ClearTable(t)
    for k in pairs(t) do
        t[k] = nil
    end
end

local function QueryZones(mapCfg, qx0, qy0, qz0, qx1, qy1, qz1, kinds, out)
    if not mapCfg then return nil end

    local hasKinds = mapCfg.has_kinds
    if hasKinds then
        local anyKindPresent = false
        for i = 1, #kinds do
            if hasKinds[kinds[i]] then
                anyKindPresent = true
                break
            end
        end
        if not anyKindPresent then return nil end
    end

    -- Format A: keyed flat arrays (`mapCfg.buckets`)
    local buckets = mapCfg.buckets
    if buckets then
        local csize = mapCfg.chunk_size or ((mapCfg.scale or 39.37) * 16.0)
        local cx0 = math.floor(qx0 / csize)
        local cx1 = math.floor(qx1 / csize)
        local cy0 = math.floor(qy0 / csize)
        local cy1 = math.floor(qy1 / csize)
        local anyHit = false
        ClearTable(out)

        for cx = cx0, cx1 do
            local col = buckets[cx]
            if col then
                for cy = cy0, cy1 do
                    local cell = col[cy]
                    if cell then
                        for ki = 1, #kinds do
                            local kind = kinds[ki]
                            if not out[kind] then
                                local arr = cell[kind]
                                if arr then
                                    for i = 1, #arr, 6 do
                                        local bx0 = arr[i]
                                        local by0 = arr[i + 1]
                                        local bz0 = arr[i + 2]
                                        local bx1 = arr[i + 3]
                                        local by1 = arr[i + 4]
                                        local bz1 = arr[i + 5]
                                        if qx0 < bx1 and qx1 > bx0 and qy0 < by1 and qy1 > by0 and qz0 < bz1 and qz1 > bz0 then
                                            out[kind] = true
                                            anyHit = true
                                            break
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if anyHit then return out end
    end

    -- Format B: tuple list (`mapCfg.zones.buckets`)
    local zones = mapCfg.zones
    if zones and zones.buckets then
        local cellSize = zones.cell_size or 512
        local cx0 = math.floor(qx0 / cellSize)
        local cx1 = math.floor(qx1 / cellSize)
        local cy0 = math.floor(qy0 / cellSize)
        local cy1 = math.floor(qy1 / cellSize)
        local anyHit = false
        ClearTable(out)

        for cx = cx0, cx1 do
            local col = zones.buckets[cx]
            if col then
                for cy = cy0, cy1 do
                    local list = col[cy]
                    if list then
                        for i = 1, #list do
                            local b = list[i]
                            local bx0, by0, bz0, bx1, by1, bz1, bk = b[1], b[2], b[3], b[4], b[5], b[6], b[7]
                            if qx0 < bx1 and qx1 > bx0 and qy0 < by1 and qy1 > by0 and qz0 < bz1 and qz1 > bz0 then
                                for ki = 1, #kinds do
                                    local kind = kinds[ki]
                                    if not out[kind] and NormalizeKind(bk, kind) then
                                        out[kind] = true
                                        anyHit = true
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if anyHit then return out end
    end

    return nil
end

local VOL_KINDS = { "water", "lava", "cobweb", "climb" }
local SURF_KINDS = { "blue_ice", "packed_ice", "ice", "soul_sand", "slime", "honey", "bed", "hay", "magma" }
local HONEY_KINDS = { "honey" }
local ICE_SLIP = { ice = 0.980, packed_ice = 0.980, blue_ice = 0.989 }

local _trRes = {}
local _trStart = Vector()
local _trEnd = Vector()
local _trMins = Vector()
local _trMaxs = Vector()
local _trReq = {
    start = _trStart,
    endpos = _trEnd,
    mins = _trMins,
    maxs = _trMaxs,
    mask = MASK_PLAYERSOLID,
    output = _trRes,
}
local _hullCache = {}
local function GetCachedHull(S)
    local key = math.floor(S * 100 + 0.5)
    local h = _hullCache[key]
    if not h then
        local hw = PlayerHalfWidth * S
        h = {
            mins = Vector(-hw, -hw, 0),
            maxs = Vector(hw, hw, PlayerHeight * S),
            duckMaxs = Vector(hw, hw, 1.47 * S),
            viewOff = Vector(0, 0, 1.62 * S),
            duckViewOff = Vector(0, 0, 1.27 * S),
        }
        _hullCache[key] = h
    end
    return h
end

local function HasSupportAt(ply, pos, mins, maxs, S)
    local inset = 0.02 * S
    local dropLimit = 0.62 * S
    _trStart:SetUnpacked(pos.x, pos.y, pos.z + 2.0)
    _trEnd:SetUnpacked(pos.x, pos.y, pos.z - dropLimit)
    _trMins:SetUnpacked(math.min(mins.x + inset, -1.0), math.min(mins.y + inset, -1.0), 0)
    _trMaxs:SetUnpacked(math.max(maxs.x - inset, 1.0), math.max(maxs.y - inset, 1.0), 4)
    _trReq.filter = ply
    util.TraceHull(_trReq)
    return _trRes.Hit
end

local function ApplySneakEdgeGuardSetup(ply, mv, S, sneakSpeed, mins, maxs, groundedOverride)
    if not cv_sneak_edge_guard then return false, false end
    if not (ply:OnGround() or groundedOverride) then return false, false end
    if not mv:KeyDown(IN_DUCK) then return false, false end

    local pos = mv:GetOrigin()
    if not HasSupportAt(ply, pos, mins, maxs, S) then
        return false, false
    end

    local ang = mv:GetMoveAngles()
    local flatAng = Angle(0, ang.y, 0)
    local fwdDir = flatAng:Forward()
    local rightDir = flatAng:Right()
    local fSpd = mv:GetForwardSpeed()
    local sSpd = mv:GetSideSpeed()
    local vel = mv:GetVelocity()
    local wish = Vector(
        fwdDir.x * fSpd + rightDir.x * sSpd,
        fwdDir.y * fSpd + rightDir.y * sSpd,
        0
    )

    local wantX = (math.abs(wish.x) > 1.0) and wish.x or vel.x
    local wantY = (math.abs(wish.y) > 1.0) and wish.y or vel.y
    if math.abs(wantX) < 0.5 and math.abs(wantY) < 0.5 then
        return false, false
    end

    local dt = math.max(engine.TickInterval(), 0.015)
    local probeDist = math.max(sneakSpeed * dt * 1.6, 2.5 * (S / 39.37))
    local blockX, blockY = false, false

    if math.abs(wantX) >= 0.5 then
        local dx = (wantX > 0) and probeDist or -probeDist
        if not HasSupportAt(ply, Vector(pos.x + dx, pos.y, pos.z), mins, maxs, S) then
            blockX = true
        end
    end
    if math.abs(wantY) >= 0.5 then
        local dy = (wantY > 0) and probeDist or -probeDist
        if not HasSupportAt(ply, Vector(pos.x, pos.y + dy, pos.z), mins, maxs, S) then
            blockY = true
        end
    end
    if not blockX and not blockY and math.abs(wantX) >= 0.5 and math.abs(wantY) >= 0.5 then
        local dx = (wantX > 0) and probeDist or -probeDist
        local dy = (wantY > 0) and probeDist or -probeDist
        if not HasSupportAt(ply, Vector(pos.x + dx, pos.y + dy, pos.z), mins, maxs, S) then
            if math.abs(wantX) <= math.abs(wantY) then
                blockX = true
            else
                blockY = true
            end
        end
    end

    if blockX then
        vel.x = 0
        wish.x = 0
    end
    if blockY then
        vel.y = 0
        wish.y = 0
    end
    if blockX or blockY then
        mv:SetVelocity(vel)
        mv:SetForwardSpeed(wish.x * fwdDir.x + wish.y * fwdDir.y)
        mv:SetSideSpeed(wish.x * rightDir.x + wish.y * rightDir.y)
    end
    return blockX, blockY
end

local function TryAutoJump(ply, mv, pos, hullMin, hullMax, S, walkSpeed)
    if not cv_auto_jump then return end
    if not ply:OnGround() or mv:KeyDown(IN_DUCK) then return end
    if mv:GetForwardSpeed() <= 1 then return end
    local vel = mv:GetVelocity()
    if vel:Length2DSqr() <= (walkSpeed * 0.25)^2 then return end

    local flatAng = Angle(0, mv:GetMoveAngles().y, 0)
    local fDir = flatAng:Forward()
    local probeLen = 0.45 * S
    _trStart:SetUnpacked(pos.x, pos.y, pos.z + 0.15 * S)
    _trEnd:SetUnpacked(pos.x + fDir.x * probeLen, pos.y + fDir.y * probeLen, pos.z + 0.15 * S)
    _trMins:SetUnpacked(hullMin.x, hullMin.y, 0)
    _trMaxs:SetUnpacked(hullMax.x, hullMax.y, 0.70 * S)
    _trReq.filter = ply
    util.TraceHull(_trReq)
    if _trRes.Hit then
        _trStart:SetUnpacked(pos.x, pos.y, pos.z + 1.08 * S)
        _trEnd:SetUnpacked(pos.x + fDir.x * (probeLen + 0.35 * S), pos.y + fDir.y * (probeLen + 0.35 * S), pos.z + 1.08 * S)
        _trMins:SetUnpacked(hullMin.x, hullMin.y, 0)
        _trMaxs:SetUnpacked(hullMax.x, hullMax.y, 1.78 * S)
        util.TraceHull(_trReq)
        if not _trRes.Hit and not _trRes.StartSolid then
            mv:SetButtons(bit.bor(mv:GetButtons(), IN_JUMP))
            mv:SetOldButtons(bit.band(mv:GetOldButtons(), bit.bnot(IN_JUMP)))
        end
    end
end

if CLIENT then
    hook.Add("CreateMove", "MCGM_OptInSwapButtons", function(cmd)
        if not cv_swap_sneak_sprint then return end
        local ply = LocalPlayer()
        if not IsValid(ply) or not ply:Alive() or ply:InVehicle() then return end
        if ply:GetMoveType() ~= MOVETYPE_WALK then return end
        local mapCfg = GetActiveMapConfig()
        if not IsPhysicsEnabled(mapCfg) then return end

        local btns = cmd:GetButtons()
        local hasSpeed = bit.band(btns, IN_SPEED) ~= 0
        local hasDuck = bit.band(btns, IN_DUCK) ~= 0
        btns = bit.band(btns, bit.bnot(bit.bor(IN_SPEED, IN_DUCK)))
        if hasSpeed then btns = bit.bor(btns, IN_DUCK) end
        if hasDuck then btns = bit.bor(btns, IN_SPEED) end
        cmd:SetButtons(btns)
    end)
end

hook.Add("SetupMove", "MCGM_PhysicsSetupMove", function(ply, mv, cmd)
    local mapCfg = GetActiveMapConfig()
    if not mapCfg then
        _G.MCGM_PHYSICS_ACTIVE = false
        return
    end
    if not IsValid(ply) then return end

    if not IsPhysicsEnabled(mapCfg) then
        _G.MCGM_PHYSICS_ACTIVE = false
        RevertPlayerDefaults(ply)
        return
    end
    _G.MCGM_PHYSICS_ACTIVE = true
    if not MCGM.SmoothFallOrigFinish or (CLIENT and not MCGM.SmoothFallOrigCam) then
        SyncSmoothFallHooks()
    end

    if not ply:Alive() or ply:InVehicle() then
        ply:SetGravity(0)
        return
    end

    local moveType = ply:GetMoveType()
    if moveType ~= MOVETYPE_WALK and moveType ~= MOVETYPE_LADDER then
        ply:SetGravity(0)
        return
    end

    SnapshotPlayerDefaults(ply)
    ply._mcgmApplied = true
    local S = tonumber(mapCfg.scale) or 39.37
    local scaleRatio = S / 39.37
    local tick = GetSimTick()
    local dt = engine.TickInterval()
    if dt <= 0 then dt = 0.015 end
    local curTime = CurTime()

    local prev = GetTickState(ply, tick - 1) or GetTickState(ply, tick - 2)
    if not prev then
        local pPos = mv:GetOrigin()
        local pVel = mv:GetVelocity()
        prev = {
            tick = tick - 1,
            on_ground = ply:OnGround(),
            from_jump = false,
            x = pPos.x, y = pPos.y, z = pPos.z,
            vx = pVel.x, vy = pVel.y, vz = pVel.z,
            peak_z = pPos.z,
            fwd_held = mv:KeyDown(IN_FORWARD),
            spd_held = mv:KeyDown(IN_SPEED),
            w_tap_time = -10,
            sprint_active = false,
            sprinting = false,
        }
    end

    -- 1. Hull & EyeHeight
    local hullMin, hullMax, hullDuckMax, viewOff, duckViewOff
    if cv_hull_parity then
        local h = GetCachedHull(S)
        hullMin = h.mins
        hullMax = h.maxs
        hullDuckMax = h.duckMaxs
        viewOff = h.viewOff
        duckViewOff = h.duckViewOff
    else
        hullMin = VANILLA_MINS
        hullMax = VANILLA_MAXS
        hullDuckMax = VANILLA_DUCK_MAXS
        viewOff = VANILLA_VIEW
        duckViewOff = VANILLA_DUCK_VIEW
    end
    ApplyHullAndEyes(ply, hullMin, hullMax, hullDuckMax, viewOff, duckViewOff)

    local activeMax = ply:Crouching() and hullDuckMax or hullMax
    local pos = mv:GetOrigin()
    local vel = mv:GetVelocity()
    local onGround = ply:OnGround()

    -- 2. StepSize (0.60 * S by default for slabs, stairs & beds)
    local stepMode = cv_step_mode
    local stepSize = 0.60 * S
    if stepMode == 1 then
        stepSize = 1.05 * S
    elseif stepMode == 2 then
        stepSize = 18.0
    end
    if math.abs(ply:GetStepSize() - stepSize) > 0.05 then
        ply:SetStepSize(stepSize)
    end
    if math.abs(ply:GetDuckSpeed() - 0.08) > 0.005 then
        ply:SetDuckSpeed(0.08)
    end
    if math.abs(ply:GetUnDuckSpeed() - 0.08) > 0.005 then
        ply:SetUnDuckSpeed(0.08)
    end

    -- 3. Detect gameplay volumes & surfaces
    local useZones = cv_block_physics
    local useClimb = cv_climb_parity
    local volHits = nil
    local surfHits = nil
    local honeySide = false

    local ctx = ply._mcgmTickCtx
    if not ctx then
        ctx = { _volOut = {}, _surfOut = {}, _honeyOut = {} }
        ply._mcgmTickCtx = ctx
    end

    if useZones or useClimb then
        local cpad = 0.06 * S
        volHits = QueryZones(
            mapCfg,
            pos.x + hullMin.x - cpad, pos.y + hullMin.y - cpad, pos.z,
            pos.x + activeMax.x + cpad, pos.y + activeMax.y + cpad, pos.z + activeMax.z,
            VOL_KINDS,
            ctx._volOut
        )
    end

    local inWater = (ply:WaterLevel() >= 1) or (useZones and volHits ~= nil and volHits.water ~= nil)
    local inLava = useZones and volHits ~= nil and volHits.lava ~= nil
    local inCobweb = useZones and volHits ~= nil and volHits.cobweb ~= nil
    local inClimb = useClimb and ((moveType == MOVETYPE_LADDER) or (volHits ~= nil and volHits.climb ~= nil))

    local surfKind = nil
    if useZones and (onGround or prev.on_ground) then
        local skinInset = 0.02 * S
        surfHits = QueryZones(
            mapCfg,
            pos.x + hullMin.x + skinInset, pos.y + hullMin.y + skinInset, pos.z - 0.14 * S,
            pos.x + activeMax.x - skinInset, pos.y + activeMax.y - skinInset, pos.z + 0.08 * S,
            SURF_KINDS,
            ctx._surfOut
        )
        if surfHits then
            for _, sk in ipairs(SURF_KINDS) do
                if surfHits[sk] then
                    surfKind = sk
                    break
                end
            end
        end
    end

    if useZones and not onGround and not inWater and not inClimb then
        local hpad = 0.07 * S
        local hHits = QueryZones(
            mapCfg,
            pos.x + hullMin.x - hpad, pos.y + hullMin.y - hpad, pos.z + 0.10 * S,
            pos.x + activeMax.x + hpad, pos.y + activeMax.y + hpad, pos.z + activeMax.z - 0.10 * S,
            HONEY_KINDS,
            ctx._honeyOut
        )
        honeySide = (hHits ~= nil and hHits.honey ~= nil)
    end

    -- 4. Speeds, Sprint Mode & Surface Modifiers
    local walkSpeed = 4.317 * S
    local sprintSpeed = 7.2 * S
    local sneakSpeed = 1.30 * S
    local fwdHeld = mv:KeyDown(IN_FORWARD)
    local spdHeld = mv:KeyDown(IN_SPEED)
    local ducking = mv:KeyDown(IN_DUCK)
    local sprintMode = cv_sprint_mode
    local sprintToggle = prev.sprint_active == true
    local wTapTime = prev.w_tap_time or -10

    if sprintMode == 1 then
        if fwdHeld and not prev.fwd_held then
            if (curTime - wTapTime) <= 0.30 then
                sprintToggle = true
            end
            wTapTime = curTime
        end
        if not fwdHeld or ducking or inCobweb then
            sprintToggle = false
        end
    elseif sprintMode == 2 then
        if spdHeld and not prev.spd_held then
            sprintToggle = not sprintToggle
        end
        if not fwdHeld or ducking or inCobweb then
            sprintToggle = false
        end
    else
        sprintToggle = spdHeld
    end

    local isMoving = fwdHeld or mv:KeyDown(IN_BACK) or mv:KeyDown(IN_MOVELEFT) or mv:KeyDown(IN_MOVERIGHT) or math.abs(mv:GetForwardSpeed()) > 0 or math.abs(mv:GetSideSpeed()) > 0
    local isSprinting = false
    if sprintMode == 0 then
        -- Hold Shift (+speed) sprints cleanly in any direction (GMod Shift-sprint parity)
        isSprinting = spdHeld and isMoving and not ducking and not inCobweb and not ply:Crouching()
    else
        isSprinting = (sprintToggle or (sprintMode == 1 and spdHeld)) and fwdHeld and (mv:GetForwardSpeed() > 0) and not ducking and not inCobweb and not ply:Crouching()
    end

    local surfMul = 1.0
    if inCobweb then
        surfMul = 0.25
    elseif inLava then
        surfMul = 0.50
    elseif inWater then
        surfMul = isSprinting and 1.00 or 0.51
    elseif surfKind == "soul_sand" or surfKind == "honey" then
        surfMul = 0.40
    elseif surfKind == "slime" then
        surfMul = 0.60
    end

    -- 5. Target Gravity & JumpPower (per-player only, global sv_gravity untouched)
    local svG = math.max(cv_sv_gravity, 1.0)
    local mcGrav = 1100.0 * scaleRatio
    local jumpPower = math.sqrt(2.0 * mcGrav * 1.252 * S)
    if surfKind == "honey" then
        jumpPower = jumpPower * 0.50
    elseif inCobweb then
        jumpPower = 0.0
    end

    local desiredG = mcGrav
    if inCobweb then
        desiredG = 0.001 * svG
    elseif inClimb and not onGround then
        desiredG = 0.001 * svG
    elseif inWater then
        desiredG = 0.18 * mcGrav
    elseif inLava then
        desiredG = 0.14 * mcGrav
    elseif not onGround and not prev.from_jump and vel.z <= 0 then
        local dropSoFar = (prev.peak_z or pos.z) - pos.z
        if dropSoFar < 1.15 * S then
            desiredG = 0.50 * mcGrav
        end
    end
    local targetGrav = desiredG / svG
    if math.abs((ply:GetGravity() or 0) - targetGrav) > 1e-4 then
        ply:SetGravity(desiredG / svG)
    end
    if math.abs((ply:GetJumpPower() or 0) - jumpPower) > 0.05 then
        ply:SetJumpPower(jumpPower)
    end

    -- 6. Apply speeds without CGameMovement duck double-cropping
    local effWalk = walkSpeed * surfMul
    local effSprint = sprintSpeed * surfMul
    local effSneak = sneakSpeed * surfMul
    local crouchRatio = math.Clamp(effSneak / math.max(effWalk, 1.0), 0.1, 1.0)

    if math.abs((ply:GetWalkSpeed() or 0) - effWalk) > 0.05 then ply:SetWalkSpeed(effWalk) end
    if math.abs((ply:GetRunSpeed() or 0) - effSprint) > 0.05 then ply:SetRunSpeed(effSprint) end
    if math.abs((ply:GetSlowWalkSpeed() or 0) - effWalk) > 0.05 then ply:SetSlowWalkSpeed(effWalk) end
    if math.abs((ply:GetCrouchedWalkSpeed() or 0) - crouchRatio) > 1e-3 then ply:SetCrouchedWalkSpeed(crouchRatio) end

    if ply:Crouching() or ducking then
        mv:SetMaxClientSpeed(effWalk)
        mv:SetMaxSpeed(effWalk)
    else
        local targetSpd = isSprinting and effSprint or effWalk
        mv:SetMaxClientSpeed(targetSpd)
        mv:SetMaxSpeed(targetSpd)
    end

    -- 7. Cobweb suppresses jumping & damps 3D velocity
    if inCobweb then
        local btns = mv:GetButtons()
        mv:SetButtons(bit.band(btns, bit.bnot(IN_JUMP)))
        vel.x = vel.x * math.exp(-12.0 * dt)
        vel.y = vel.y * math.exp(-12.0 * dt)
        vel.z = math.max(vel.z * math.exp(-10.0 * dt), -0.35 * S)
        mv:SetVelocity(vel)
    end

    -- 8. Water / Lava swimming & buoyancy
    if inWater and not inCobweb and not inClimb then
        local btns = mv:GetButtons()
        if ply:WaterLevel() < 1 then
            -- Custom zone water swimming (not Source BSP water brush)
            if mv:KeyDown(IN_JUMP) then
                vel.z = Lerp(math.Clamp(dt * 10.0, 0, 1), vel.z, 2.2 * S)
                mv:SetButtons(bit.band(btns, bit.bnot(IN_JUMP)))
            elseif ducking then
                vel.z = Lerp(math.Clamp(dt * 10.0, 0, 1), vel.z, -2.2 * S)
            else
                vel.z = Lerp(math.Clamp(dt * 4.0, 0, 1), vel.z, -0.45 * S)
            end
            mv:SetVelocity(vel)
        end
    elseif inLava and not inCobweb and not inClimb then
        if mv:KeyDown(IN_JUMP) then
            vel.z = Lerp(math.Clamp(dt * 6.0, 0, 1), vel.z, 1.0 * S)
            mv:SetButtons(bit.band(mv:GetButtons(), bit.bnot(IN_JUMP)))
        else
            vel.z = math.max(vel.z * math.exp(-6.0 * dt), -0.8 * S)
        end
        mv:SetVelocity(vel)
    end

    -- 9. Continuous Spacebar hold jump
    if cv_hold_jump_bhop and onGround and mv:KeyDown(IN_JUMP) and not inWater and not inLava and not inClimb and not inCobweb then
        mv:SetOldButtons(bit.band(mv:GetOldButtons(), bit.bnot(IN_JUMP)))
    end

    -- 10. Optional MC Auto-Jump (disabled by default)
    if not inWater and not inClimb and not inCobweb then
        TryAutoJump(ply, mv, pos, hullMin, hullMax, S, walkSpeed)
    end

    -- 11. Full axis-separated + diagonal Sneak Edge Guard
    local blockX, blockY = false, false
    if not inWater and not inLava and not inClimb and not inCobweb then
        blockX, blockY = ApplySneakEdgeGuardSetup(ply, mv, S, effSneak, hullMin, activeMax, prev.guard_grounded)
    end

    -- Save tick context for FinishMove
    ctx.tick = tick
    ctx.S = S
    ctx.dt = dt
    ctx.walkSpeed = walkSpeed
    ctx.sprintSpeed = sprintSpeed
    ctx.sneakSpeed = effSneak
    ctx.jumpPower = jumpPower
    ctx.onGroundStart = onGround
    ctx.inWater = inWater
    ctx.inLava = inLava
    ctx.inCobweb = inCobweb
    ctx.inClimb = inClimb
    ctx.honeySide = honeySide
    ctx.surfKind = surfKind
    ctx.surfMul = surfMul
    ctx.sprinting = isSprinting
    ctx.sprintToggle = sprintToggle
    ctx.wTapTime = wTapTime
    ctx.fwdHeld = fwdHeld
    ctx.spdHeld = spdHeld
    ctx.hullMin = hullMin
    ctx.activeMax = activeMax
    ctx.blockX = blockX
    ctx.blockY = blockY
    ctx.prePos = pos
    ctx.preVel = vel
    ctx.prev = prev
end)

hook.Add("FinishMove", "MCGM_PhysicsFinishMove", function(ply, mv)
    local mapCfg = GetActiveMapConfig()
    if not mapCfg or not IsPhysicsEnabled(mapCfg) then return end
    if not IsValid(ply) or not ply:Alive() or ply:InVehicle() then return end

    local ctx = ply._mcgmTickCtx
    local tick = GetSimTick()
    if not ctx or ctx.tick ~= tick then return end

    local S = ctx.S
    local dt = ctx.dt
    local prev = ctx.prev
    local pos = mv:GetOrigin()
    local vel = mv:GetVelocity()
    local onGround = ply:OnGround()
    local ducking = mv:KeyDown(IN_DUCK)

    -- 1. Ladder / Vine smooth climbing (runs in FinishMove after Source LadderMove)
    if ctx.inClimb then
        local climbSpd = 3.0 * S
        local fSpd = mv:GetForwardSpeed()
        if ducking then
            vel.z = 0
            vel.x = vel.x * 0.5
            vel.y = vel.y * 0.5
        elseif (mv:KeyDown(IN_JUMP) or fSpd > 10) and not onGround then
            vel.z = climbSpd
        elseif fSpd < -10 and not onGround then
            vel.z = -climbSpd
        elseif not onGround then
            vel.z = -climbSpd
        else
            vel.z = 0
        end
        mv:SetVelocity(vel)
    end

    -- 2. Honey side wall slide (prevents fast vertical falling while hugging honey block wall)
    if ctx.honeySide and not onGround and not ctx.inWater and not ctx.inClimb then
        local maxSlide = -1.5 * S
        if vel.z < maxSlide then
            vel.z = maxSlide
            mv:SetVelocity(vel)
        end
    end

    -- 3. Sprint-jump / airborne anti-bunnyhop horizontal speed cap
    -- Preserves external knockback (explosions/physgun) above sprintSpeed * 1.45.
    if prev.on_ground and not onGround and vel.z > ctx.jumpPower * 0.55 and not ctx.inWater and not ctx.inCobweb then
        local jumpCap = ctx.sprinting and (ctx.sprintSpeed * 0.88) or (ctx.walkSpeed * 0.96)
        local hSpd = math.sqrt(vel.x * vel.x + vel.y * vel.y)
        if hSpd > jumpCap and hSpd <= ctx.sprintSpeed * 1.45 and hSpd > 0.01 then
            local scale = jumpCap / hSpd
            vel.x = vel.x * scale
            vel.y = vel.y * scale
            mv:SetVelocity(vel)
        end
    elseif not onGround and not ctx.inWater and not ctx.inClimb and not ctx.inCobweb then
        local airCap = ctx.sprinting and (ctx.sprintSpeed * 0.90) or (ctx.walkSpeed * 1.02)
        local hSpd = math.sqrt(vel.x * vel.x + vel.y * vel.y)
        if hSpd > airCap and hSpd <= ctx.sprintSpeed * 1.45 and hSpd > 0.01 then
            local scale = airCap / hSpd
            vel.x = vel.x * scale
            vel.y = vel.y * scale
            mv:SetVelocity(vel)
        end
    end

    -- 4. Ice slipperiness (preserve horizontal inertia on ice without altering sv_friction)
    local slip = ICE_SLIP[ctx.surfKind or ""]
    if slip and onGround and not ctx.inWater and not ctx.inCobweb then
        local decay = math.pow(slip, dt * 20.0)
        local flatAng = Angle(0, mv:GetMoveAngles().y, 0)
        local fDir = flatAng:Forward()
        local rDir = flatAng:Right()
        local wish = Vector(
            fDir.x * mv:GetForwardSpeed() + rDir.x * mv:GetSideSpeed(),
            fDir.y * mv:GetForwardSpeed() + rDir.y * mv:GetSideSpeed(),
            0
        )
        local wishLen = wish:Length2D()
        local targetSpd = ctx.sprinting and ctx.sprintSpeed or (ducking and ctx.sneakSpeed or ctx.walkSpeed)
        local ix = prev.vx * decay
        local iy = prev.vy * decay
        if wishLen > 1.0 then
            local accel = 220.0 * (S / 39.37) * dt
            ix = ix + (wish.x / wishLen) * accel
            iy = iy + (wish.y / wishLen) * accel
        end
        local spd = math.sqrt(ix * ix + iy * iy)
        if spd > targetSpd * 1.15 and spd > 0.01 then
            ix = ix * ((targetSpd * 1.15) / spd)
            iy = iy * ((targetSpd * 1.15) / spd)
        end
        vel.x = ix
        vel.y = iy
        mv:SetVelocity(vel)
    end

    -- 5. Sneak edge guard final position clamp (prevents diagonal corner slip)
    local guardGrounded = false
    if cv_sneak_edge_guard and ducking and (prev.on_ground or prev.guard_grounded) and not ctx.inWater and not ctx.inLava and not ctx.inClimb and not ctx.inCobweb then
        if not onGround or not HasSupportAt(ply, pos, ctx.hullMin, ctx.activeMax, S) then
            local testX = ctx._tmpTestX or Vector(); ctx._tmpTestX = testX
            local testY = ctx._tmpTestY or Vector(); ctx._tmpTestY = testY
            local safePos = ctx._tmpSafePos or Vector(); ctx._tmpSafePos = safePos
            testX:SetUnpacked(pos.x, prev.y, prev.z)
            testY:SetUnpacked(prev.x, pos.y, prev.z)
            safePos:SetUnpacked(prev.x, prev.y, prev.z)
            if HasSupportAt(ply, testX, ctx.hullMin, ctx.activeMax, S) then
                safePos.x = pos.x
            else
                vel.x = 0
            end
            if HasSupportAt(ply, testY, ctx.hullMin, ctx.activeMax, S) then
                safePos.y = pos.y
            else
                vel.y = 0
            end
            if safePos.x == prev.x and safePos.y == prev.y then
                vel.x = 0
                vel.y = 0
            end
            vel.z = math.max(vel.z, 0)
            mv:SetOrigin(safePos)
            mv:SetVelocity(vel)
            pos = safePos
            onGround = true
            guardGrounded = true
        end
    end

    -- 5b. Prevent StayOnGround downward step-teleport: convert sudden downward snaps (> 0.22*S) into smooth gravity falls
    if prev.on_ground and onGround and not guardGrounded and not ducking and ply:GetMoveType() == MOVETYPE_WALK then
        local stepDrop = pos.z - (prev.z or pos.z)
        if stepDrop < (-0.22 * S) and stepDrop >= (-1.15 * S) then
            pos.z = prev.z
            mv:SetOrigin(pos)
            ply:SetGroundEntity(NULL)
            vel.z = math.min(vel.z, -18.0 * (S / 39.37))
            mv:SetVelocity(vel)
            onGround = false
        end
    end

    -- 5c. Refresh landing surface kind when transitioning from air -> ground so falls > 1 tick
    -- still detect slime/bed bounce and slime/bed/hay/honey fall damage mitigation.
    if onGround and not prev.on_ground and not ctx.surfKind and cv_block_physics then
        local skinInset = 0.02 * S
        local landSurf = QueryZones(
            mapCfg,
            pos.x + ctx.hullMin.x + skinInset, pos.y + ctx.hullMin.y + skinInset, pos.z - 0.14 * S,
            pos.x + ctx.activeMax.x - skinInset, pos.y + ctx.activeMax.y - skinInset, pos.z + 0.08 * S,
            SURF_KINDS,
            ctx._surfOut
        )
        if landSurf then
            for _, sk in ipairs(SURF_KINDS) do
                if landSurf[sk] then
                    ctx.surfKind = sk
                    break
                end
            end
        end
    end

    -- 6. Slime & Bed vertical landing bounce
    local bounced = false
    if onGround and not prev.on_ground and not ducking and (ctx.surfKind == "slime" or ctx.surfKind == "bed") then
        local impactVZ = math.min(prev.vz or 0, ctx.preVel.z or 0)
        if impactVZ < -2.0 * S then
            local mult = (ctx.surfKind == "slime") and 0.80 or 0.66
            local minBounce = (ctx.surfKind == "slime") and (1.5 * S) or (1.2 * S)
            vel.z = math.max(math.abs(impactVZ) * mult, minBounce)
            ply:SetGroundEntity(NULL)
            pos.z = pos.z + 1.0
            mv:SetOrigin(pos)
            mv:SetVelocity(vel)
            onGround = false
            bounced = true
        end
    end

    -- 7. Peak Z tracking & Server-side MC Fall Damage ((blocks - 3) * 5 with water/slime/bed/hay/cobweb/honey mitigation)
    local peakZ = prev.peak_z or pos.z
    if onGround or ctx.inWater or ctx.inCobweb or ctx.inClimb or ctx.honeySide or bounced then
        if not prev.on_ground and onGround and cv_fall_damage then
            local fallBlocks = (peakZ - pos.z) / S
            if fallBlocks > 3.0 and not ctx.inWater and not ctx.inCobweb and not ctx.inClimb and not ctx.honeySide then
                local suppressSlime = (ctx.surfKind == "slime" and not ducking)
                if not suppressSlime then
                    local rawDmg = math.floor(fallBlocks - 3.0) * 5.0
                    if ctx.surfKind == "bed" then
                        rawDmg = rawDmg * 0.50
                    elseif ctx.surfKind == "hay" or ctx.surfKind == "honey" then
                        rawDmg = rawDmg * 0.20
                    elseif ctx.inLava then
                        rawDmg = rawDmg * 0.50
                    end
                    if rawDmg >= 1.0 and SERVER then
                        local dmgInfo = DamageInfo()
                        dmgInfo:SetDamage(rawDmg)
                        dmgInfo:SetDamageType(DMG_FALL)
                        dmgInfo:SetAttacker(game.GetWorld())
                        dmgInfo:SetInflictor(game.GetWorld())
                        ply:TakeDamageInfo(dmgInfo)
                    end
                end
            end
        end
        peakZ = pos.z
    else
        if pos.z > peakZ then
            peakZ = pos.z
        end
    end

    -- Client-side CalcView short-fall landing camera cushion (step easing uses SmoothViewOnStairs origin.z in CalcView)
    if CLIENT and IsFirstTimePredicted() and ply == LocalPlayer() then
        ply.mcgm_sf_cam_z = 0
        if cv_smooth_step_cam then
            local maxLag = 0.75 * S
            if onGround and not prev.on_ground and not bounced then
                local impactVZ = math.min(prev.vz or 0, ctx.preVel.z or 0)
                if impactVZ < -80.0 then
                    local cushion = math.Clamp(math.abs(impactVZ) * 0.025, 2.0, 10.0)
                    ply._mcgmCamStepZ = math.Clamp((ply._mcgmCamStepZ or 0) + cushion, -maxLag, maxLag)
                end
            end
            ply._mcgmSpLastZ = pos.z
            ply._mcgmSpLastGround = onGround
        end
    end

    local fromJump = prev.from_jump == true
    if onGround then
        fromJump = false
    elseif prev.on_ground and not onGround and vel.z > ctx.jumpPower * 0.5 then
        fromJump = true
    end

    StoreTickState(
        ply, tick,
        onGround, guardGrounded, fromJump,
        pos.x, pos.y, pos.z,
        vel.x, vel.y, vel.z,
        peakZ,
        ctx.fwdHeld, ctx.spdHeld, ctx.wTapTime, ctx.sprintToggle, ctx.sprinting
    )
end)

hook.Add("OnPlayerHitGround", "MCGM_SoftShortLanding", function(ply, inWater, onFloater, speed)
    if inWater or onFloater then return end
    local mapCfg = GetActiveMapConfig()
    if not mapCfg or not IsPhysicsEnabled(mapCfg) then return end
    if not IsValid(ply) then return end
    if (speed or 0) < 480 then
        ply:SetViewPunchAngles(Angle(0, 0, 0))
        ply:SetViewPunchVelocity(Angle(0, 0, 0))
    end
end)

if SERVER then
    hook.Add("PlayerSpawn", "MCGM_PhysicsSpawn", function(ply)
        local mapCfg = GetActiveMapConfig()
        if not mapCfg or not IsPhysicsEnabled(mapCfg) then return end
        local S = tonumber(mapCfg.scale) or 39.37
        ply._mcgmHullCache = nil
        if cv_hull_parity then
            local h = GetCachedHull(S)
            ApplyHullAndEyes(ply, h.mins, h.maxs, h.duckMaxs, h.viewOff, h.duckViewOff)
        end
        ply._mcgmRing = nil
    end)

    hook.Add("GetFallDamage", "MCGM_PhysicsFallDamageOverride", function(ply, speed)
        local mapCfg = GetActiveMapConfig()
        if not mapCfg or not IsPhysicsEnabled(mapCfg) then return end
        if cv_fall_damage then
            return 0
        end
    end)

    hook.Add("EntityTakeDamage", "MCGM_TrackExternalHurt", function(ent, dmg)
        if IsValid(ent) and ent:IsPlayer() and dmg:IsDamageType(DMG_BURN) then
            ent._mcgmLastBurnHurt = CurTime()
        end
    end)

    hook.Add("PlayerPostThink", "MCGM_LavaZoneBurn", function(ply)
        local mapCfg = GetActiveMapConfig()
        if not mapCfg or not IsPhysicsEnabled(mapCfg) or not cv_block_physics then return end
        if not IsValid(ply) or not ply:Alive() or ply:InVehicle() then return end
        local ctx = ply._mcgmTickCtx
        if not ctx then return end

        local isMagma = (ctx.surfKind == "magma" and ply:OnGround() and not ply:KeyDown(IN_DUCK))
        if not ctx.inLava and not isMagma then return end

        local now = CurTime()
        if (now - (ply._mcgmLastBurnHurt or 0)) < 0.5 then return end
        ply._mcgmLastBurnHurt = now
        local dmgInfo = DamageInfo()
        dmgInfo:SetDamage(ctx.inLava and 4 or 2)
        dmgInfo:SetDamageType(DMG_BURN)
        dmgInfo:SetAttacker(game.GetWorld())
        dmgInfo:SetInflictor(game.GetWorld())
        ply:TakeDamageInfo(dmgInfo)
    end)
end

if CLIENT then
    local function ResetCalcViewStepState(ply)
        if IsValid(ply) then
            ply._mcgmCamStepZ = 0
            ply._mcgmLastOriginZ = nil
            ply._mcgmLastViewOffZ = nil
            ply._mcgmLastGround = nil
        end
    end

    hook.Add("CalcView", "MCGM_PhysicsStepCamera", function(ply, origin, angles, fov, znear, zfar)
        local mapCfg = GetActiveMapConfig()
        if not mapCfg or not IsPhysicsEnabled(mapCfg) then
            ResetCalcViewStepState(ply)
            return
        end
        if not IsValid(ply) or ply ~= LocalPlayer() or not ply:Alive() or ply:InVehicle() then
            ResetCalcViewStepState(ply)
            return
        end
        if ply:GetMoveType() ~= MOVETYPE_WALK or ply:ShouldDrawLocalPlayer() then
            ResetCalcViewStepState(ply)
            return
        end

        local dt = math.Clamp(RealFrameTime(), 0, 0.05)
        local onGround = ply:OnGround()
        local hVel = ply:GetVelocity()
        local hSpeed = math.sqrt(hVel.x * hVel.x + hVel.y * hVel.y)
        local S = tonumber(mapCfg.scale) or 39.37

        if cv_smooth_step_cam then
            local curViewOffZ = ply:GetCurrentViewOffset().z
            local curOriginZ = origin.z
            if ply._mcgmLastOriginZ ~= nil and ply._mcgmLastViewOffZ ~= nil and onGround and ply._mcgmLastGround then
                local viewOffDz = curViewOffZ - ply._mcgmLastViewOffZ
                local camDz = (curOriginZ - ply._mcgmLastOriginZ) - viewOffDz
                local smoothBudget = math.max(150.0 * dt + 2.5, 4.0)
                if math.abs(camDz) > smoothBudget and math.abs(camDz) <= (1.15 * S) then
                    local excess = (camDz > 0) and (camDz - smoothBudget) or (camDz + smoothBudget)
                    local maxLag = 0.75 * S
                    ply._mcgmCamStepZ = math.Clamp((ply._mcgmCamStepZ or 0) - excess, -maxLag, maxLag)
                end
            end
            ply._mcgmLastOriginZ = curOriginZ
            ply._mcgmLastViewOffZ = curViewOffZ
            ply._mcgmLastGround = onGround
        else
            ply._mcgmCamStepZ = 0
            ply._mcgmLastOriginZ = nil
            ply._mcgmLastViewOffZ = nil
            ply._mcgmLastGround = nil
        end

        local offset = ply._mcgmCamStepZ or 0
        if cv_smooth_step_cam then
            if math.abs(offset) >= 0.05 then
                offset = offset * math.exp(-16.0 * dt)
                if math.abs(offset) < 0.05 then
                    offset = 0
                end
                ply._mcgmCamStepZ = offset
            else
                ply._mcgmCamStepZ = 0
                offset = 0
            end
        else
            offset = 0
        end

        local bobZ = 0
        local bobPitch = 0
        local bobRoll = 0
        local bobEnabled = cv_view_bobbing

        if bobEnabled then
            local movingOnGround = onGround and hSpeed > 10.0
            local targetBlend = movingOnGround and 1.0 or 0.0
            local blend = Lerp(math.Clamp(dt * 8.0, 0, 1), ply._mcgmBobBlend or 0, targetBlend)
            ply._mcgmBobBlend = blend
            if blend > 0.01 then
                local bobFreq = math.Clamp(hSpeed / (4.317 * S), 0.2, 1.15) * 2.8
                if movingOnGround then
                    ply._mcgmBobPhase = ((ply._mcgmBobPhase or 0) + bobFreq * math.pi * dt) % (2.0 * math.pi)
                end
                local phase = ply._mcgmBobPhase or 0
                local bobAmp = math.Clamp(hSpeed / (5.612 * S), 0.15, 0.85) * blend
                bobZ = (math.cos(phase * 2.0) - 1.0) * 0.5 * (0.55 * bobAmp)
                bobPitch = math.sin(phase * 2.0) * (0.12 * bobAmp)
                bobRoll = math.cos(phase) * (0.18 * bobAmp)
            else
                ply._mcgmBobBlend = 0
                ply._mcgmBobPhase = 0
            end
        else
            ply._mcgmBobBlend = 0
        end

        if math.abs(offset) < 0.05 and math.abs(bobZ) < 0.01 and math.abs(bobPitch) < 0.01 and math.abs(bobRoll) < 0.01 then
            return
        end

        return {
            origin = Vector(origin.x, origin.y, origin.z + offset + bobZ),
            angles = Angle(angles.p + bobPitch, angles.y, angles.r + bobRoll),
            fov = fov,
            znear = znear,
            zfar = zfar,
            drawviewer = false,
        }
    end)

    hook.Add("PopulateToolMenu", "MCGM_PhysicsMenu", function()
        spawnmenu.AddToolMenuOption("Utilities", "MCGM", "MCGM_MinecraftPhysics", "Minecraft Physics", "", "", function(panel)
            panel:ClearControls()
            panel:Help("Map-scoped Minecraft movement, hull, step, climbing & block surface parity.")
            panel:Help("Live toggle (no map restart): chat !mcphysics or console mcgm_toggle_physics")

            panel:Button("Toggle Minecraft / Vanilla GMod Physics (Live)", "mcgm_toggle_physics")

            panel:CheckBox("Enable Minecraft Physics (mcgm_physics_enabled)", "mcgm_physics_enabled")
            local presetRow = panel:ComboBox("Preset Mode (mcgm_physics_enabled)", "mcgm_physics_enabled")
            presetRow:AddChoice("Auto (Map Default: -1)", "-1")
            presetRow:AddChoice("Vanilla GMod Physics (0)", "0")
            presetRow:AddChoice("Minecraft Parity On (1)", "1")

            local stepBox = panel:ComboBox("Step Height Mode (mcgm_step_mode)", "mcgm_step_mode")
            stepBox:AddChoice("0: Default 0.6*S (Slabs, Stairs & Beds)", "0")
            stepBox:AddChoice("1: Full-Block 1.05*S (Full-Block Step Up)", "1")
            stepBox:AddChoice("2: Vanilla GMod (18 HU)", "2")

            panel:CheckBox("Minecraft Fall Damage (mcgm_fall_damage)", "mcgm_fall_damage")
            panel:CheckBox("Minecraft View Bobbing (mcgm_view_bobbing)", "mcgm_view_bobbing")

            panel:CheckBox("MC Player Hull & Eye Height (22.8x70.1)", "mcgm_hull_parity")
            panel:CheckBox("Sneak Edge Prevention", "mcgm_sneak_edge_guard")

            local sprintBox = panel:ComboBox("Sprint Input Mode", "mcgm_sprint_mode")
            sprintBox:AddChoice("Hold +speed (Shift)", "0")
            sprintBox:AddChoice("Double-Tap W + Hold", "1")
            sprintBox:AddChoice("Toggle on +speed", "2")

            panel:CheckBox("Continuous Hold-Space Jump", "mcgm_hold_jump_bhop")
            panel:CheckBox("Auto-Jump 1-Block Ledges", "mcgm_auto_jump")
            panel:CheckBox("Surface Physics (Water/Ice/Slime/Honey/Bed/Web)", "mcgm_block_physics")
            panel:CheckBox("Ladder & Vine Climb Parity", "mcgm_climb_parity")
            panel:CheckBox("Smooth Camera Step Interpolation (Client)", "mcgm_smooth_step_cam")
            panel:CheckBox("Swap Ctrl/Shift (Opt-In MC Keys)", "mcgm_swap_sneak_sprint")
            panel:CheckBox("Fix Dynamic Light Chunk Flashing (Client)", "mcgm_fix_dlight_chunks")
        end)
    end)
end
